package com.zc.agent.core.modules.tool.service;
import com.fasterxml.jackson.databind.ObjectMapper;import com.zc.agent.core.modules.conversation.client.RegistryAgentClient;import com.zc.agent.core.modules.tool.dto.*;import com.zc.agent.core.modules.tool.model.RegistryAgentTool;import com.zc.agent.core.modules.tool.vo.ToolDebugResponse;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Service;import java.time.*;import java.util.*;
/** 以统一四阶段标准执行并留存外部 Tool/MCP 兼容性矩阵。 */
@Service public class ToolProtocolCompatibilityService{private final RegistryAgentClient registry;private final ToolDebugService debug;private final JdbcTemplate jdbc;private final ObjectMapper mapper;public ToolProtocolCompatibilityService(RegistryAgentClient r,ToolDebugService d,JdbcTemplate j,ObjectMapper m){registry=r;debug=d;jdbc=j;mapper=m;}
 public Map<String,Object> run(Long toolId,ToolCompatibilityRequest request,String authorization){RegistryAgentTool tool=registry.getRuntimeToolDetail(toolId,authorization);long start=System.nanoTime();List<Map<String,Object>>checks=new ArrayList<>();boolean config=configured(tool);checks.add(check("configuration",config,config?"配置完整":"缺少 Provider、transport 或 endpoint/command"));ToolDebugResponse health=config?debug.healthCheck(toolId,authorization):null;boolean connectivity=health!=null&&health.success();checks.add(check("connectivity",connectivity,health==null?"未执行":health.message()));boolean discovery=connectivity&&discoveryPassed(tool,health);checks.add(check("discovery",discovery,discovery?"能力发现成功":"未获得可调用操作"));ToolDebugResponse invocation=discovery?debug.debugTool(toolId,new ToolDebugRequest(false,request==null?"":request.inputText(),request==null?Map.of():Optional.ofNullable(request.arguments()).orElse(Map.of())),authorization):null;boolean invoked=invocation!=null&&invocation.success();checks.add(check("invocation",invoked,invocation==null?"未执行":invocation.message()));String status=invoked?"compatible":connectivity?"partially_compatible":"incompatible";String failed=firstFailed(checks);String reason=checks.stream().filter(v->failed.equals(v.get("stage"))).map(v->String.valueOf(v.get("message"))).findFirst().orElse("");String protocol=health==null?"":String.valueOf(health.output().getOrDefault("protocolVersion",tool.transportType()));String code="COMPAT_"+UUID.randomUUID().toString().replace("-","").toUpperCase();long latency=Duration.ofNanos(System.nanoTime()-start).toMillis();jdbc.update("INSERT INTO tool_protocol_compatibility_runs(run_code,tool_id,tool_code,provider_type,transport_type,protocol_version,environment_code,status,configuration_passed,connectivity_passed,discovery_passed,invocation_passed,latency_ms,failure_stage,failure_reason,checks,output_snapshot) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,CAST(? AS JSONB),CAST(? AS JSONB))",code,toolId,tool.toolCode(),safe(tool.providerType()),safe(tool.transportType()),protocol,safe(tool.environmentCode()),status,config,connectivity,discovery,invoked,latency,failed,reason,json(checks),json(Map.of("health",health==null?Map.of():health.output(),"invocation",invocation==null?Map.of():invocation.output())));return detail(code);}
 public List<Map<String,Object>> matrix(){return jdbc.queryForList("SELECT DISTINCT ON(provider_type,transport_type,tool_id) * FROM tool_protocol_compatibility_runs ORDER BY provider_type,transport_type,tool_id,created_at DESC");}public List<Map<String,Object>> history(Long toolId){return jdbc.queryForList("SELECT * FROM tool_protocol_compatibility_runs WHERE tool_id=? ORDER BY created_at DESC LIMIT 100",toolId);}private Map<String,Object>detail(String code){return jdbc.queryForMap("SELECT * FROM tool_protocol_compatibility_runs WHERE run_code=?",code);}private boolean configured(RegistryAgentTool t){if(t.providerType()==null||t.providerType().isBlank())return false;if("internal".equals(t.providerType()))return true;if("mcp".equals(t.providerType())&&"stdio".equals(t.transportType()))return t.invokeConfig()!=null&&t.invokeConfig().hasNonNull("command");return t.endpoint()!=null&&!t.endpoint().isBlank();}private boolean discoveryPassed(RegistryAgentTool t,ToolDebugResponse h){if(!"mcp".equals(t.providerType()))return true;Object d=h.output().get("discovery");return d!=null&&!String.valueOf(d).isBlank()&&!"{}".equals(String.valueOf(d));}private Map<String,Object>check(String stage,boolean passed,String message){return Map.of("stage",stage,"passed",passed,"message",message==null?"":message);}private String firstFailed(List<Map<String,Object>> c){return c.stream().filter(v->!Boolean.TRUE.equals(v.get("passed"))).map(v->String.valueOf(v.get("stage"))).findFirst().orElse("");}private String safe(String v){return v==null?"":v;}private String json(Object v){try{return mapper.writeValueAsString(v);}catch(Exception e){return "{}";}}}
